package baritone.cache;

import java.io.IOException;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;

final class CacheFiles {

    private CacheFiles() {}

    /**
     * Replaces {@code target} with a fully written {@code source} in one step where the file system allows it, so a
     * save that gets cut off (a crash, or the JVM exiting while a worker thread is still writing) leaves the previous
     * file intact instead of a truncated one.
     */
    static void moveIntoPlace(Path source, Path target) throws IOException {
        try {
            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
        } catch (AtomicMoveNotSupportedException e) {
            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
        }
    }
}
